fn x_ssq(dst: mem1d_dsd) void {
  // (trm 2) B 1: a scalar loop (simulator 142 cycles against the tree's 271; a stride-0
  // accumulate is wrong on hardware, 0530)
  var ss: f32 = 0.0;
  var h: u16 = 0;
  while (h < Hc) : (h += 1) { ss += x[h] * x[h]; }
  @fmovs(dst, ss);
}
